 private final BuyReplacementSellPriceCandidateSet source; private final BuyReplacementSpreadEligibilityOutcome outcome; private final List<BuyReplacementSellPriceCandidate> candidates; private final List<BuyReplacementPositiveSpreadCandidate> positiveSpreadCandidates; private final long evaluatedAt;
 BuyReplacementSpreadEligibilityAssessment(BuyReplacementSellPriceCandidateSet s,BuyReplacementSpreadEligibilityOutcome o,List<BuyReplacementSellPriceCandidate> c,List<BuyReplacementPositiveSpreadCandidate> p,long at){source=s;outcome=o;candidates=Collections.unmodifiableList(new ArrayList<>(c));positiveSpreadCandidates=Collections.unmodifiableList(new ArrayList<>(p));evaluatedAt=at;}
